import math
from collections import defaultdict
docs = ["the cache keeps the hot keys in the cache", "the deploy broke the cache",
        "roll back the deploy", "the hot path skips the cache",
        "a cache miss after the deploy", "the miss rate fell after the roll back"]
index = defaultdict(dict)                 # term to {docID: [positions]}
for d, text in enumerate(docs, 1):
    for p, term in enumerate(text.lower().split(), 1):
        index[term].setdefault(d, []).append(p)
N = len(docs)
idf = {t: math.log10(N / len(p)) for t, p in index.items()}
length = defaultdict(float)
for t, p in index.items():
    for d, pos in p.items(): length[d] += (len(pos) * idf[t]) ** 2
def AND(terms):                           # merge from the rarest term
    terms = sorted(terms, key=lambda t: len(index[t]))
    result = set(index[terms[0]])
    for t in terms[1:]: result &= set(index[t])
    return sorted(result)
def phrase(t1, t2):
    return [d for d in AND([t1, t2])
            if any(p + 1 in index[t2][d] for p in index[t1][d])]
def rank(query, k=3):                     # ntc.ntc cosine
    q = {t: idf[t] for t in query.split() if t in index}
    qlen = math.sqrt(sum(w * w for w in q.values()))
    acc = defaultdict(float)
    for t, wq in q.items():
        for d, pos in index[t].items(): acc[d] += wq * len(pos) * idf[t]
    s = {d: a / math.sqrt(length[d]) / qlen for d, a in acc.items()}
    return [(d, round(s[d], 3)) for d in sorted(s, key=lambda d: -s[d])[:k]]
print(AND(["the", "cache"]), phrase("the", "cache"), phrase("roll", "back"))
print(rank("the cache miss"))
